  now=self.now();profile_id=profile_id or self.gate_service.settings.profile_id;gate=self.gate_service.evaluate(seller_id,marketplace_id,profile_id);runs=self.repository.list_sync_runs(seller_id,marketplace_id,profile_id,limit);latest=runs[0] if runs else None;success=self.repository.latest_successful_sync(seller_id,marketplace_id,profile_id);failure=self.repository.latest_failed_sync(seller_id,marketplace_id,profile_id);active=self.repository.active_sync_run(seller_id,marketplace_id,profile_id);stale=bool(active and datetime.fromisoformat(active["started_at"])<now-timedelta(minutes=30));recent24=self.repository.count_sync_runs_since(seller_id,marketplace_id,profile_id,now-timedelta(hours=24));recent7=self.repository.count_sync_runs_since(seller_id,marketplace_id,profile_id,now-timedelta(days=7));totals=self.repository.aggregate_sync_counts_since(seller_id,marketplace_id,profile_id,now-timedelta(days=7));rate=None if not runs else round(sum(item.success for item in runs)/len(runs)*100,2);health="never_synced" if not runs else "stale" if stale else "running" if active else "blocked" if not gate.allowed else "failing" if len(runs)>=2 and all(not item.success for item in runs[:2]) else "degraded" if latest and not latest.success and success else "healthy" if latest and latest.success else "idle";public=lambda item:item.public_dict() if item else None;age=lambda item:int((now-item.started_at).total_seconds()) if item else None
